const $=id=>document.getElementById(id);let page=0,admin=false,selected='',source=null;let data={};try{data=JSON.parse(localStorage.getItem('dangha2026')||'{}')}catch{}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function editable(key,val,tag='p',cls=''){return `<${tag} class="${cls}" data-key="${key}" ${admin?'contenteditable="true"':''}>${esc(data[key]??val)}</${tag}>`}
function illustration(){return `<svg class="landscape" viewBox="0 0 700 360" preserveAspectRatio="xMidYMid slice" xmlns="http://www.w3.org/2000/svg"><rect width="700" height="360" fill="#e0e8d7"/><circle cx="565" cy="70" r="35" fill="#f6f3cd"/><path d="M0 185L130 100 275 186 395 120 570 190 700 120V360H0" fill="#bbcda8"/><path d="M0 245Q170 180 340 242T700 230V360H0" fill="#809b72"/><path d="M320 360L410 242 455 242 465 360" fill="#d4cfab"/><rect x="105" y="148" width="380" height="119" fill="#f4f0da"/><rect x="135" y="127" width="330" height="28" fill="#49634c"/><rect x="270" y="100" width="70" height="167" fill="#e7e4cb"/><path d="M260 100L305 76 350 100" fill="#49634c"/><g fill="#6e8e81">${Array.from({length:12},(_,i)=>`<rect x="${125+(i%6)*59}" y="${169+Math.floor(i/6)*46}" width="33" height="28"/>`).join('')}</g><rect x="290" y="228" width="32" height="39" fill="#3c5a49"/><g fill="#42664d"><circle cx="65" cy="215" r="40"/><circle cx="535" cy="216" r="35"/><circle cx="620" cy="208" r="49"/></g><text x="350" y="334" text-anchor="middle" fill="#f5f4df" font-size="12" letter-spacing="5">DANGHA · OUR GROWING DAYS</text></svg>`}
// 사진 칸: 등록된 사진, 표지 일러스트, 빈 사진 자리 순으로 표시합니다.
function photo(key,label='사진'){let p=data[key],btn=admin?`<button data-photo="${key}">＋ 사진 편집</button>`:'';if(p)return `<div class="photo filled" style="width:${p.width}%;aspect-ratio:${p.ratio};border-radius:${p.radius}"><img src="${p.url}" alt="편집자가 등록한 소식지 사진">${btn}</div>`;if(key==='p0photo')return `<div class="photo cover-art">${illustration()}${btn}</div>`;return `<div class="photo ph"><span class="photo-symbol">▧</span><span>${label}</span>${btn}</div>`}
// 기사별 사진 키. 예전 지면의 대표 사진(p0photo 등)은 첫 칸으로 이어 씁니다.
function slotKey(key,i){return i===1&&/^p\da$/.test(key)?key.slice(0,2)+'photo':key+'photo'+i}
function shots(key,n){return n?`<div class="shots" data-n="${n}">${Array.from({length:n},(_,i)=>photo(slotKey(key,i+1),'행사 사진 '+(i+1))).join('')}</div>`:''}
function waiting(key,body){return !body&&!data[key+'b']}
function item([key,title,body,n=0]){return `<article class="item${waiting(key,body)?' waiting':''}">${waiting(key,body)?'<span class="need">내용 필요</span>':''}${editable(key+'t',title,'h4')}${shots(key,n)}${editable(key+'b',body)}</article>`}
// 기사 순서를 지키면서 각 단의 분량이 비슷해지도록 나눕니다(위→아래, 왼쪽→오른쪽 순서로 읽힘).
function weight([key,title,body,n=0]){const b=data[key+'b']??body;return 60+(data[key+'t']??title).length*1.5+b.length+(b.match(/\n\n/g)||[]).length*30+(n?(n>1?190:150):0)+(b?0:50)}
function split(items,k){const w=items.map(weight),pre=[0];w.forEach(x=>pre.push(pre.at(-1)+x));const best=[];for(let j=0;j<=k;j++)best.push(Array(items.length+1).fill([Infinity,[]]));best[0][0]=[0,[]];for(let j=1;j<=k;j++)for(let i=0;i<=items.length;i++)for(let m=0;m<=i;m++){const c=Math.max(best[j-1][m][0],pre[i]-pre[m]);if(c<best[j][i][0])best[j][i]=[c,[...best[j-1][m][1],items.slice(m,i)]]}return best[k][items.length][1].filter(g=>g.length)}
function section(s){const span=s.span||4,k=Math.min(span,s.items.length);return `<section class="sec" style="--span:${span}"><header class="sechead"><h3>${s.title}</h3><span>${s.dept}</span></header><div class="cols" style="--k:${k}">${split(s.items,k).map(g=>`<div class="col">${g.map(item).join('')}</div>`).join('')}</div></section>`}
function lead([key,title,body,n=0]){return `<article class="lead${waiting(key,body)?' waiting':''}"><div class="leadshots">${shots(key,n)}</div><div class="leadtext"><span class="tag">SPECIAL REPORT · 2026</span>${editable(key+'t',title,'h2')}${editable(key+'b',body)}</div></article>`}
function render(){const pg=pages[page],n=pages.length;
 $('nav').innerHTML=pages.map((s,i)=>`<button class="${i===page?'active':''}" data-page="${i}">${i+1}면 <span>${s.name}</span></button>`).join('');$('section').textContent=`THE NEWSPAPER / ${String(page+1).padStart(2,'0')} — ${pg.name}`;$('count').textContent=`${page+1} / ${n}`;$('prev').disabled=page===0;$('next').disabled=page===n-1;$('nextBottom').textContent=page===n-1?'1면으로 돌아가기 ↗':'다음 면 읽기 →';
 let h=pg.cover?`<div class="mastline"><span>함께 성장하는 우리들의 이야기</span><span>2026 · 특별호 · 편집용 초안</span></div><div class="masthead">당하브릿지</div><div class="mastsub">D A N G H A　 B R I D G E</div><div class="dateline"><span>당하중학교 소식지</span><span>${pg.name}</span><span>제 1 면</span></div>`:`<div class="runhead"><b>당하브릿지</b><span>${pg.name}</span><span>2026 특별호 · 제 ${page+1} 면</span></div>`;
 if(pg.cover){const [k,t,b]=pg.lead;h+=`<section class="greeting">${photo('p0greetphoto','교장선생님 사진')}<div><span class="tag">발간사 · 교장선생님 인사말</span>${editable('p0greett','교장선생님 인사말','h2')}${editable('p0greetb','이곳에 교장선생님 인사말이 들어갑니다.\n원고를 받으면 관리자 편집 모드에서 이 글을 클릭해 바로 수정할 수 있습니다.')}${editable('p0greets','당하중학교장 ○○○','p','sign')}</div></section><div class="cover"><article class="coverstory${waiting(k,b)?' waiting':''}"><span class="tag">COVER STORY · 2026</span>${editable(k+'t',t,'h2')}${photo('p0photo')}${editable(k+'b',b)}</article><aside class="schoolbox"><span class="tag">OUR SCHOOL · 학교 소개</span>${pg.side.map(item).join('')}</aside></div>`}
 else if(pg.lead)h+=lead(pg.lead);
 if(pg.sections)h+=`<div class="secs">${pg.sections.map(section).join('')}</div>`;
 if(pg.clubs)h+=`<header class="sechead club-head"><h3>서로 다른 관심, 함께 빛나는 우리</h3><span>CLUB STORIES · 01—${clubs.length} · 동아리 소개는 실제 활동 내용으로 수정해 주세요</span></header><div class="clubs">${clubs.map((c,i)=>`<article class="club${waiting('c'+i,clubText[i])?' waiting':''}"><span class="num">${String(i+1).padStart(2,'0')}</span>${editable('c'+i+'t',c,'h4')}${photo('c'+i+'photo','활동사진')}${editable('c'+i+'b',clubText[i]??'')}</article>`).join('')}</div>`;
 h+=`<div class="folio"><span>DANGHA BRIDGE · 2026</span><span>${String(page+1).padStart(2,'0')}</span></div>`;
 $('paper').innerHTML=`<div class="fit">${h}</div>`;$('savebar').hidden=!admin;
 document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>go(+b.dataset.page));document.querySelectorAll('[data-key]').forEach(el=>el.oninput=()=>{data[el.dataset.key]=el.innerText});document.querySelectorAll('[data-photo]').forEach(b=>b.onclick=()=>openCrop(b.dataset.photo));fitPaper()}
// 한 면이 A3 한 장(297×420mm)에 들어가도록 넘치는 지면만 비율에 맞춰 축소합니다.
// 인쇄할 때는 A3 인쇄 폭(281mm, 여백 8mm)으로 잠시 맞춘 뒤 다시 계산합니다.
function fitPaper(print=false){const p=$('paper'),f=p.firstElementChild;f.style.zoom=1;if(!print&&matchMedia('(max-width:700px)').matches)return;if(print)Object.assign(p.style,{width:'281mm',padding:'8mm',aspectRatio:'auto'});const cs=getComputedStyle(p),room=print?f.getBoundingClientRect().width/265*388*.98:p.clientWidth*420/297-parseFloat(cs.paddingTop)-parseFloat(cs.paddingBottom);const fits=z=>{f.style.zoom=z;return f.getBoundingClientRect().height<=room+1};if(!fits(1)){let lo=.3,hi=1;for(let i=0;i<9;i++){const m=(lo+hi)/2;fits(m)?lo=m:hi=m}f.style.zoom=lo.toFixed(4)}if(print)p.removeAttribute('style')}
addEventListener('resize',()=>fitPaper());addEventListener('beforeprint',()=>fitPaper(true));addEventListener('afterprint',()=>fitPaper());
function go(n){page=n;render();$('nav').scrollIntoView({behavior:'smooth',block:'start'})}function toast(s){$('toast').textContent=s;$('toast').style.display='block';setTimeout(()=>$('toast').style.display='none',3000)}$('prev').onclick=()=>go(Math.max(0,page-1));$('next').onclick=()=>go(Math.min(pages.length-1,page+1));$('nextBottom').onclick=()=>go((page+1)%pages.length);$('admin').onclick=()=>{$('login').showModal();$('pw').focus()};$('unlock').onclick=()=>{if($('pw').value==='1234'){admin=true;$('login').close();$('pw').value='';$('error').textContent='';render()}else $('error').textContent='비밀번호를 확인해 주세요.'};$('pw').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();$('unlock').click()}};$('exit').onclick=()=>{admin=false;render()};$('save').onclick=()=>{try{localStorage.setItem('dangha2026',JSON.stringify(data));toast('이 브라우저에 저장했습니다.')}catch{toast('저장 공간이 부족합니다. 백업을 내보내 주세요.')}};$('export').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(data)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='당하브릿지-2026-백업.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};$('import').onchange=async e=>{try{let v=JSON.parse(await e.target.files[0].text());if(!v||Array.isArray(v)||typeof v!=='object')throw Error();for(let [k,x]of Object.entries(v)){if(!/^(p\d+(?:[abcd][tb]|e[a-z0-9]+[tb]|photo|(?:[abcd]|e[a-z0-9]+)photo[1-3]|greet(?:[tbs]|photo))|c\d+(?:[tb]|photo))$/.test(k))throw Error();if(k.endsWith('photo')||/photo[1-3]$/.test(k)){if(typeof x!=='object'||!/^data:image\/(png|jpeg|webp);base64,/.test(x.url)||!Number.isFinite(x.ratio)||x.ratio<=0||!Number.isFinite(x.width)||x.width<20||x.width>100||!['0','18px','50%'].includes(x.radius))throw Error()}else if(typeof x!=='string')throw Error()}data=v;render();toast('백업을 불러왔습니다. 저장 버튼으로 보관하세요.')}catch{toast('유효한 소식지 백업 파일을 선택해 주세요.')}e.target.value=''};$('print').onclick=()=>window.print();
function openCrop(key){selected=key;source=null;$('upload').value='';$('zoom').value=1;$('x').value=50;$('y').value=50;$('width').value=data[key]?.width||100;$('height').value=300;$('shape').value='rect';$('crop').showModal();if(data[key]){let im=new Image();im.onload=()=>{source=im;draw()};im.src=data[key].url}else draw()}function dims(){let shape=$('shape').value;let w=600*+$('width').value/100,h=+$('height').value;if(shape==='circle')h=w;if(shape.startsWith('portrait'))h=w*4/3;return {w,h,shape}}function draw(){let {w,h,shape}=dims();let c=$('canvas');c.width=Math.round(w*1.6);c.height=Math.round(h*1.6);let ctx=c.getContext('2d');ctx.fillStyle='#dce3d1';ctx.fillRect(0,0,c.width,c.height);if(source){let scale=Math.max(c.width/source.width,c.height/source.height)*+$('zoom').value;let iw=source.width*scale,ih=source.height*scale;ctx.drawImage(source,-(iw-c.width)*+$('x').value/100,-(ih-c.height)*+$('y').value/100,iw,ih)}else{ctx.fillStyle='#718166';ctx.font='20px sans-serif';ctx.textAlign='center';ctx.fillText('사진을 선택해 주세요',c.width/2,c.height/2)}c.style.borderRadius=shape==='circle'?'50%':/round/i.test(shape)?'18px':'0';$('wo').value=$('width').value+'%';$('ho').value=Math.round(h)+'px';$('height').disabled=shape==='circle'||shape.startsWith('portrait')}['width','height','shape','zoom','x','y'].forEach(id=>$(id).oninput=draw);$('upload').onchange=e=>{let file=e.target.files[0];if(!file)return;if(!file.type.startsWith('image/')){toast('이미지 파일을 선택해 주세요.');return}let url=URL.createObjectURL(file),im=new Image();im.onload=()=>{source=im;draw();URL.revokeObjectURL(url)};im.onerror=()=>{toast('이 이미지를 열 수 없습니다. JPG 또는 PNG로 다시 선택해 주세요.');URL.revokeObjectURL(url)};im.src=url};$('apply').onclick=()=>{if(!source){toast('사진을 먼저 선택해 주세요.');return}let {w,h,shape}=dims();data[selected]={url:$('canvas').toDataURL('image/jpeg',.85),width:+$('width').value,ratio:w/h,radius:shape==='circle'?'50%':/round/i.test(shape)?'18px':'0'};$('crop').close();render()};$('delete').onclick=()=>{delete data[selected];$('crop').close();render()};$('closecrop').onclick=()=>$('crop').close();
document.querySelector('footer small').textContent='행사 기사 출처: 학교 행사 현황 조사 표(v2, 2026.10.15 확인) 및 추가 행사 자료(2026.10.30 반영). 미제공 자료는 내용 필요로 표시했습니다. 기존 편집 내용은 우선 유지됩니다.';render();
